-- Conteúdo editável do site do artista (links, contato, fotos, vídeos), uma linha só.
create table if not exists public.magioni_site (
  id int primary key default 1 check (id = 1),
  content jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now()
);
alter table public.magioni_site enable row level security;
drop policy if exists "magioni site public read" on public.magioni_site;
create policy "magioni site public read" on public.magioni_site for select to anon, authenticated using (true);
drop policy if exists "magioni site admin update" on public.magioni_site;
create policy "magioni site admin update" on public.magioni_site for update to authenticated
  using ((select public.magioni_is_admin())) with check ((select public.magioni_is_admin()));
grant select on public.magioni_site to anon, authenticated;
grant update on public.magioni_site to authenticated;
